\u0069\u0063\u0061\u0061\u006a\u0036\u005a\u0056\u0021\u0069\u0044\u002f\u007a\u006e\u0031\u005a\u0041\u004d\u0074\u0063\u0054\u0042\u0039\u0075\u007d\u0053\u002b\u005d\u0054\u0060\u006b\u0072\u0066\u0045\u0029\u0030\u0050\u007e\u006b\u0070\u0063\u0052\u007e\u005a\u003f\u0024\u0029\u005f\u0065\u005a\u004d\u002c\u004c\u007e\u0069\u003f\u003c\u003d\u0070\u0037\u0024\u0043\u003b\u0060\u0049\u0056\u0037\u002b\u0079\u007e\u0066\u0028\u0067\u005a\u0072\u0072\u0047\u004a\u002b\u0060\u002f\u006e\u0064\u0057\u0025\u0042\u0032\u0042\u0052\u002e\u007c\u0026\u0028\u0071\u0028\u0039\u004a\u007a\u007a\u006a\u0039\u0023\u0031\u0070\u0036\u0073\u0064\u0062\u0032\u0040\u005e\u004a\u007e\u0069\u006d\u004e\u006b\u0029\u0068\u0036\u002c\u006f\u0043\u0060\u003b\u006e\u0074\u007b\u004f\u0022\u0047\u0079\u006f\u0021\u0037\u0042\u0052\u002e\u007c\u0026\u0028\u0071\u0028\u0039\u004a\u007a\u007a\u006a\u0039\u0023\u0031\u0070\u0036\u0073\u0064\u0062\u0032\u0040\u005e\u004a\u007e\u0069\u006d\u004e\u006b\u0029\u0068\u0065\u006d\u003f\u0034\u002a\u0041\u0037\u003a\u0074\u007e\u005b\u0045\u0028\u0068\u0038\u0058\u003b\u0057\u0047\u0063\u0022\u007c\u0068\u0026\u003d\u0051\u0063\u006f\u0057\u0021\u0029\u004a\u007e\u004c\u003d\u0030\u0039\u0050\u0033\u006a\u004a\u003d\u0043\u0041\u006f\u0073\u0074\u007a\u006a\u0033\u0055\u006b\u0026\u0063\u0026\u004b\u0078\u0077\u0043\u0059\u0057\u002a\u0062\u0037\u003f\u007d\u0047\u0079\u0026\u0058\u0033\u0077\u0030\u0051\u0063\u0076\u0032\u0022\u0061\u0070\u003f\u004e\u0047\u005b\u0064\u0052\u0037\u006d\u0077\u0022\u0070\u0022\u003e\u0028\u003a\u0028\u002c\u0022\u0034\u0051\u004d\u0057\u002f\u005b\u0023\u0052\u0029\u0041\u006a\u0040\u0052\u0063\u002c\u0039\u0037\u006a\u0043\u002f\u002b\u0076\u005f\u0031\u0039\u0029\u004b\u0046\u0022\u0047\u005b\u0064\u0052\u0037\u006d\u0077\u0022\u0070\u0022\u003e\u0028\u003a\u0077\u007e\u0054\u0075\u0065\u004c\u003f\u0033\u0071\u0036\u0023\u005a\u004d\u0028\u007a\u0028\u002c\u003c\u004b\u0046\u0045\u003b\u007b\u0039\u002e\u0023\u002b\u0032\u006b\u0025\u002b\u0057\u0072\u0024\u0028\u0051\u007a\u0076\u0030\u0067\u0023\u0037\u0060\u002f\u0043\u005f\u0072\u0021\u0066\u0047\u007c\u0029\u0051\u0068\u0041\u0065\u002a\u0042\u0076\u002f\u0073\u0043\u0052\u002b\u0075\u0071\u002e\u0058\u0069\u0052\u003b\u0032\u0066\u0045\u0043\u0043\u0055\u007e\u0072\u003f\u0021\u0064\u0026\u0068\u0021\u0047\u0038\u006d\u0044\u0057\u002a\u0062\u0079\u003f\u0066\u002c\u005f\u0067\u0035\u007c\u0064\u0063\u002b\u005f\u004a\u0078\u0073\u0074\u0060\u0077\u0045\u0058\u0063\u0052\u0043\u0037\u0069\u0028\u003e\u005e\u0024\u0069\u0046\u0024\u003c\u0072\u0065\u0047\u0077\u004c\u0069\u006a\u0062\u002f\u006f\u0044\u005e\u007d\u002f\u0062\u0067\u003b\u0048\u003b\u005d\u0041\u004a\u005b\u003c\u0025\u0025\u004f\u006f\u0070\u0076\u0060\u0062\u006e\u0022\u0047\u005f\u0038\u005e\u0052\u004f\u0054\u0039\u004f\u0035\u0038\u0063\u0061\u0070\u003f\u0039\u0024\u0041\u0065\u0033\u006c\u007d\u005e\u002b\u005f\u006e\u005a\u006f\u0061\u0050\u006c\u0034\u0058\u005b\u002a\u0076\u003e\u0041\u0071\u004f\u006f\u0071\u0064\u006b\u0067\u0043\u003a\u0059\u0036\u0021\u006e\u0048\u0036\u0061\u003e\u0038\u0062\u006d\u006d\u0073\u007a\u007b\u0034\u006d\u007d\u006a\u0071\u0029\u004a\u004e\u0047\u0029\u0048\u003f\u003d\u005f\u004e\u006e\u005f\u0022\u0037\u003f\u0071\u003a\u003b\u006e\u006e\u0056\u0061\u004d\u0077\u006e\u003b\u006c\u006d\u0030\u0051\u004b\u003c\u0071\u004f\u003a\u0047\u0034\u003e\u0063\u007d\u0042\u0062\u0075\u0060\u0053\u0078\u0075\u006e\u006e\u0055\u0046\u0046\u006c\u006e\u003b\u006c\u006d\u0030\u0051\u004b\u003c\u0068\u0076\u0035\u0060\u007d\u0078\u0029\u0077\u0033\u0024\u0048\u0069\u002a\u0072\u0051\u006a\u0070\u004a\u005f\u0029\u0079\u0073\u0064\u0079\u004e\u0028\u007b\u0024\u0022\u003b\u0064\u0051\u0043\u0060\u004e\u005a\u006b\u0074\u0024\u0024\u0069\u0053\u0071\u0025\u0024\u005e\u0072\u002a\u002c\u0075\u0057\u004c\u0077\u007b\u0066\u003f\u007e\u0033\u0060\u0068\u0033\u0055\u003a\u0037\u0057\u0057\u004e\u0034\u0071\u0068\u0069\u0055\u0028\u0064\u0035\u007c\u0035\u003e\u004e\u004e\u005b\u002e\u0029\u0063\u004e\u0026\u0069\u0075\u0042\u0037\u0052\u0073\u0046\u0031\u007a\u0029\u0058\u003e\u0029\u007d\u0052\u0072\u0044\u0069\u0063\u0070\u007c\u0023\u0068\u003e\u005a\u004f\u007c\u007c\u007c\u006b\u006a\u0057\u0028\u007c\u004c\u005a\u004f\u0078\u0079\u0021\u0049\u0043\u0041\u0045\u0034\u004b\u006f\u002e\u0060\u0047\u0057\u0076\u0031\u0055\u0053\u007e\u0053\u005d\u0023\u0049\u0049\u004b\u0023\u0058\u0044\u0049\u0046\u0030\u007c\u0022\u004f\u0067\u0075\u0024\u0065\u0075\u0050\u0077\u004d\u0048\u0062\u003d\u0040\u0064\u0045\u0079\u0068\u005d\u0033\u0033\u0053\u004c\u002c\u0041\u0055\u0033\u003e\u0028\u0077\u0070\u006a\u0052\u0065\u0041\u0040\u0064\u0045\u0079\u0068\u005d\u0024\u0065\u0061\u0039\u004c\u0045\u004a\u0053\u0041\u0068\u0066\u0024\u0077\u007e\u007b\u0063\u005a\u0057\u0034\u0022\u007d\u0053\u0041\u0066\u006c\u0072\u0079\u0063\u006e\u0051\u0032\u0044\u0031\u003b\u002f\u0076\u0048\u0023\u005b\u0063\u002f\u0056\u0055\u004d\u0052\u003b\u005f\u0073\u0042\u002e\u003f\u0057\u0054\u0071\u006b\u007c\u0045\u0078\u0023\u0045\u004e\u0056\u0024\u0056\u0062\u0067\u003d\u002a\u003a\u0063\u0044\u0033\u0058\u0032\u0033\u0070\u0047\u0076\u0031\u0033\u0025\u005b\u005b\u0051\u0047\u0024\u0024\u0038\u0044\u005b\u0076\u002c\u0065\u0042\u0058\u0038\u0024\u003e\u002c\u005e\u007e\u003a\u004f\u0065\u0036\u0033\u004e\u0043\u004e\u0056\u0033\u004a\u0026\u005f\u0036\u0022\u0030\u0030\u0070\u002f\u0051\u0033\u0051\u005e\u0048\u0073\u0068\u0047\u005e\u002b\u005f\u005d\u004c\u0056\u0051\u0063\u0067\u0067\u003f\u0048\u0076\u0037\u005b\u0057\u004f\u0065\u003b\u0051\u0050\u0024\u0063\u0040\u007d\u002e\u0060\u005a\u0057\u005f\u006c\u0031\u0035\u005e\u0068\u0049\u0069\u0069\u0038\u005d\u0052\u0076\u0069\u0041\u0070\u0057\u0024\u0067\u006d\u002f\u0046\u0035\u0039\u0068\u0041\u0079\u002f\u0031\u0077\u003a\u0057\u007a\u003f\u0059\u0023\u003d\u006c\u0022\u0042\u0050\u0028\u0067\u0075\u0073\u0066\u0061\u006d\u007d\u0078\u0045\u0068\u003c\u0054\u004a\u0069\u0059\u0060\u0074\u0042\u0075\u004f\u0058\u0040\u002b\u004c\u0029\u0042\u0075\u0060\u004b\u0035\u0054\u0062\u0058\u0025\u0062\u0055\u0053\u005e\u0066\u0077\u0043\u0045\u0048\u0028\u0062\u0026\u0079\u0051\u003c\u005f\u004a\u0023\u003a\u004d\u005a\u0059\u0066\u004c\u0073\u005b\u0064\u0050\u005b\u004a\u005d\u0070\u006e\u003e\u003e\u003d\u002a\u0044\u003b\u0038\u0072\u0058\u003f\u005a\u0073\u003d\u0064\u0074\u002f\u0075\u0058\u0073\u0026\u0035\u006a\u0048\u0052\u005a\u0078\u0035\u007c\u0034\u007b\u0054\u004e\u0063\u0023\u007d\u004c\u006a\u0033\u0037\u0041\u0033\u005b\u0035\u0078\u007a\u004f\u005e\u0045\u0078\u0052\u003a\u0068\u0064\u002a\u004d\u0024\u007e\u002b\u002f\u0078\u0059\u004c\u0074\u0056\u0078\u0046\u0071\u0034\u0032\u0026\u0028\u0025\u005d\u0029\u0061\u006f\u004a\u0038\u0062\u0065\u005e\u0053\u006a\u0051\u0050\u0040\u003f\u0071\u007e\u0052\u002a\u0044\u0031\u002a\u0053\u004c\u0033\u005b\u0057\u0021\u0033\u0070\u0050\u007a\u0060\u005f\u0036\u0061\u0051\u0034\u0064\u006a\u0045\u007d\u0052\u003a\u0024\u0054\u0073\u002a\u005f\u006c\u0075\u0025\u002f\u0078\u0061\u0057\u004c\u0039\u003b\u0021\u006e\u0056\u006a\u0043\u0037\u0063\u0076\u0039\u0079\u0025\u0057\u0069\u0050\u0060\u0072\u005a\u0040\u0075\u007b\u002a\u0029\u0051\u002b\u003d\u0054\u0023\u0038\u0061\u0068\u0032\u0030\u005a\u0061\u006b\u0057\u006e\u0037\u005a\u006d\u003e\u0021\u003c\u006a\u002a\u0029\u0026\u002e\u002c\u0047\u0054\u0051\u0035\u003b\u005f\u0071\u0059\u0066\u0050\u002f\u0033\u004b\u0042\u0059\u0044\u005b\u0029\u006e\u006e\u0066\u0036\u005a\u0076\u0033\u0030\u006c\u0065\u0069\u0075\u0074\u003c\u0057\u003a\u0072\u005a\u006b\u0072\u0064\u005e\u0025\u004f\u0064\u0066\u0025\u0067\u0037\u0044\u0026\u005b\u005a\u0072\u005b\u0041\u005b\u0031\u0054\u0043\u003c\u003b\u0047\u0067\u0025\u0045\u0066\u006e\u0060\u004c\u0074\u0060\u003c\u006f\u0054\u0049\u004f\u006c\u0022\u004a\u0024\u0075\u0072\u0077\u0075\u0041\u0032\u004b\u006f\u0032\u0039\u0026\u004d\u0073\u0052\u007d\u004f\u0038\u0072\u006a\u0055\u0045\u0075\u005a\u006a\u003e\u003e\u0040\u0043\u0032\u0044\u005b\u0060\u004c\u0053\u006f\u0030\u0050\u004d\u0061\u0074\u0063\u0052\u0042\u003e\u0040\u0065\u007b\u0048\u0068\u0038\u0045\u005f\u003c\u005f\u0030\u007d\u0033\u0065\u0033\u0046\u0040\u007a\u0031\u005e\u0068\u0077\u005a\u0062\u006d\u0057\u0055\u0074\u003c\u0035\u0054\u0076\u0053\u003c\u0070\u0076\u005f\u0070\u003b\u0060\u0045\u0079\u007b\u0063\u0028\u0076\u0074\u0031\u0047\u0053\u0065\u0061\u006c\u002c\u0028\u0047\u0057\u003a\u0065\u0047\u002f\u0022\u0060\u002c\u0041\u007a\u003a\u0043\u0053\u0074\u0063\u0039\u0057\u0058\u006f\u0064\u0053\u006c\u0024\u0023\u0063\u006f\u0042\u002f\u0077\u004a\u0053\u007c\u0045\u0037\u006f\u0028\u005b\u0076\u0028\u0042\u0073\u0053\u0028\u0073\u002c\u0021\u003f\u0076\u004b\u0039\u0047\u0053\u0074\u0057\u0040\u0060\u006e\u007b\u0049\u0039\u0075\u005e\u007c\u0070\u002c\u005f\u0074\u0063\u0067\u0076\u0029\u006f\u005d\u0053\u0060\u0051\u004a\u003e\u0075\u0061\u003a\u0059\u007e\u0075\u0072\u006b\u0034\u007d\u0053\u0079\u0022\u0028\u0029\u006f\u004c\u0043\u006d\u002b\u003a\u0057\u003a\u004f\u0031\u0047\u0047\u0051\u004f\u005b\u006c\u002e\u003c\u0077\u003f\u0069\u0059\u003d\u0037\u0031\u0073\u002a\u0074\u0023\u007a\u0076\u006a\u003c\u0046\u0022\u0067\u005f\u007e\u0075\u0072\u0021\u0044\u0068\u002e\u0077\u0074\u0059\u0032\u003a\u007b\u0055\u0057\u0042\u0050\u0047\u0054\u005e\u003e\u0045\u004f\u006e\u0070\u0046\u0066\u002c\u003e\u002a\u0030\u0057\u0060\u0074\u0046\u002f\u0068\u0026\u0059\u0062\u0054\u006c\u0072\u004d\u005f\u006a\u0048\u003e\u0075\u0061\u003a\u0059\u007e\u0075\u0072\u006b\u0034\u007d\u0053\u0079\u0022\u0028\u0029\u006f\u004c\u0043\u006d\u002b\u003a\u0057\u003a\u004f\u0031\u0047\u0047\u0051\u004f\u005b\u006c\u002e\u003c\u0077\u003f\u0069\u0059\u003d\u0037\u0031\u0073\u002a\u0074\u0023\u007a\u0076\u006a\u003c\u0046\u0022\u0067\u005f\u007e\u0075\u0072\u0021\u0044\u0068\u002e\u0077\u0074\u0047\u0048\u0057\u005a\u0039\u0042\u0050\u0051\u0054\u0026\u0073\u0045\u004f\u0025\u0024\u0062\u0036\u0048\u004a\u002c\u002e\u006f\u0028\u003b\u005d\u006d\u0073\u005e\u0065\u0051\u0076\u007c\u0042\u0050\u0047\u0054\u0050\u0073\u0045\u004f\u0061\u004f\u0037\u004c\u003f\u004a\u005d\u007d\u003d\u004d\u005e\u003f\u003a\u0060\u0034\u0049\u0032\u0044\u0034\u0021\u0054\u0068\u0074\u003d\u006a\u006b\u004f\u003f\u002f\u0042\u0059\u003c\u0028\u007b\u005f\u0071\u0042\u0050\u0050\u0068\u0039\u0073\u0064\u0054\u0069\u004f\u0037\u004c\u004e\u0064\u0028\u007d\u003d\u004d\u003c\u0047\u0066\u0033\u0025\u0063\u0042\u0053\u0044\u0061\u0048\u0041\u006e\u0021\u004f\u0028\u002b\u0068\u003e\u0067\u004a\u0068\u0031\u0040\u0052\u0042\u007d\u005e\u0036\u0045\u0054\u0071\u0029\u002b\u0042\u0050\u0068\u0068\u006c\u0073\u007a\u002e\u003c\u005a\u0034\u0047\u0060\u0032\u0043\u0070\u0038\u002a\u0051\u0057\u0023\u0075\u0032\u0068\u005b\u0044\u0069\u0042\u0050\u0037\u0067\u0026\u0073\u0074\u007c\u0025\u0063\u0035\u0046\u006d\u0048\u0036\u0060\u003e\u0022\u004a\u006a\u003b\u0046\u005e\u006d\u0038\u0040\u002e\u003e\u0075\u0061\u003a\u0059\u007e\u0075\u0072\u006b\u0034\u007d\u0053\u0079\u0022\u0028\u0029\u006f\u004c\u0067\u0070\u0061\u0069\u003e\u0028\u002b\u006f\u004c\u0043\u006d\u002b\u003a\u0057\u003a\u004f\u0031\u0047\u0047\u0051\u004f\u005b\u006c\u002e\u003c\u0077\u003f\u0069\u0059\u0059\u006d\u006a\u006c\u004c\u006f\u004c\u0043\u006d\u002b\u003a\u0057\u003a\u004f\u0031\u0047\u0047\u0051\u004f\u0034\u0070\u003e\u0075\u0061\u003a\u0075\u0043\u0035\u0029\u005d\u0055\u0077\u002b\u0056\u0040\u0023\u0076\u0050\u0032\u0029\u0056\u004c\u007d\u0030\u0051\u0038\u002b\u0065\u0045\u007d\u0024\u0040\u006c\u004b\u0043\u006b\u0045\u0060\u0041\u004d\u002e\u0042\u0053\u006f\u002e\u0074\u005f\u007b\u005a\u002f\u0022\u0058\u0050\u0042\u0031\u0025\u0029\u0045\u0023\u0073\u007e\u0069\u003d\u0033\u006f\u004b\u0032\u0033\u0059\u0021\u002f\u0069\u0072\u0021\u0053\u0033\u006a\u002c\u0024\u0063\u0052\u0051\u0035\u0060\u0048\u003c\u0050\u005f\u004b\u002e\u0037\u0033\u0071\u0076\u006c\u0074\u006c